+import { describe, it } from "node:test";
+import assert from "node:assert/strict";
+import { verifyAutoSeoSignature } from "./autoseo.ts";
+
+describe("verifyAutoSeoSignature", () => {
+  it("should return true for a valid signature", async () => {
+    const secret = "test-secret-1234567890";
+    const payload = "/api/autoseo/health";
+    const timestamp = Math.floor(Date.now() / 1000).toString();
+    const dataToVerify = `${timestamp}.${payload}`;
+
+    const enc = new TextEncoder();
+    const keyMaterial = await crypto.subtle.importKey(
+      "raw",
+      enc.encode(secret),
+      { name: "HMAC", hash: "SHA-256" },
+      false,
+      ["sign"]
+    );
+    const signatureBuffer = await crypto.subtle.sign(
+      "HMAC",
+      keyMaterial,
+      enc.encode(dataToVerify)
+    );
+    const signatureHex = Array.from(new Uint8Array(signatureBuffer))
+      .map((b) => b.toString(16).padStart(2, "0"))
+      .join("");
+
+    const isValid = await verifyAutoSeoSignature(secret, payload, signatureHex, timestamp);
+    assert.equal(isValid, true);
+  });
