+import type { Context, MiddlewareHandler, Next } from "hono";
+import type { AppEnv } from "./index.ts";
+
+/**
+ * Verify HMAC-SHA256 signature for UAPP requests.
+ * @param secret The shared secret for HMAC.
+ * @param payload The raw string payload of the request (or URL path if GET).
+ * @param signature The hex-encoded HMAC-SHA256 signature from the client.
+ * @param timestamp The timestamp (Unix seconds) when the request was sent.
+ * @param maxAgeSeconds Maximum age of the request in seconds to prevent replay attacks.
+ */
+export async function verifyAutoSeoSignature(
+  secret: string,
+  payload: string,
+  signature: string,
+  timestamp: string,
+  maxAgeSeconds = 300
+): Promise<boolean> {
+  const ts = parseInt(timestamp, 10);
+  if (isNaN(ts)) return false;
+
+  const now = Math.floor(Date.now() / 1000);
+  if (Math.abs(now - ts) > maxAgeSeconds) {
+    return false;
+  }
+
+  const enc = new TextEncoder();
+  const keyMaterial = await crypto.subtle.importKey(
+    "raw",
+    enc.encode(secret),
+    { name: "HMAC", hash: "SHA-256" },
+    false,
+    ["verify"]
+  );
+
+  // Convert hex signature to ArrayBuffer
+  const sigBytes = new Uint8Array(
+    signature.match(/[\da-f]{2}/gi)?.map((h) => parseInt(h, 16)) || []
+  );
+  
+  if (sigBytes.length !== 32) return false;
+
+  const dataToVerify = enc.encode(`${timestamp}.${payload}`);
+  
+  try {
+    const isValid = await crypto.subtle.verify(
+      "HMAC",
+      keyMaterial,
+      sigBytes,
+      dataToVerify
+    );
+    return isValid;
+  } catch {
+    return false;
+  }
+}
+
+export function requireAutoSeoSignature(): MiddlewareHandler<AppEnv> {
+  return async (c: Context<AppEnv>, next: Next): Promise<Response | void> => {
+    const secret = c.env.AUTOSEO_SECRET;
+    if (!secret) {
+      return c.json({ error: "AutoSEO is not configured" }, 500);
+    }
+
+    const signature = c.req.header("X-AutoSEO-Signature");
+    const timestamp = c.req.header("X-AutoSEO-Timestamp");
+
+    if (!signature || !timestamp) {
+      return c.json({ error: "Missing AutoSEO signature or timestamp headers" }, 401);
+    }
+
+    let payload = "";
+    if (c.req.method === "GET") {
+      const url = new URL(c.req.url);
+      payload = url.pathname + url.search;
+    } else {
+      payload = await c.req.text();
+    }
+
+    const isValid = await verifyAutoSeoSignature(secret, payload, signature, timestamp);
+    if (!isValid) {
+      return c.json({ error: "Invalid or expired AutoSEO signature" }, 403);
+    }
+
+    await next();
